w.ActiveFragmentCount>=6&&view.LastFragmentStarts.Length>=6,"flight active from cells");wait=EditorApplication.timeSinceStartup;stage=2;return;}if(stage==2){if(EditorApplication.timeSinceStartup-wait<5.0)return;Req(session.State==GameState.Playing&&view.ShownStage==2&&view.PresentedEnergy==155&&!view.CompletionActive&&view.ActiveFragmentCount==0,"transition completes/unlocks");Req(view.CompletionPlayCount==1,"transition once");int count=view.transform.parent.childCount;session.Retry();flow.ShowHome();flow.Play();Req(!view.FeedbackActive&&!view.CompletionActive&&view.ActiveFragmentCount==0&&session.State==GameState.Playing,"cleanup flows");Req(view.transform.parent.childCount==count,"hierarchy stable");flow.ShowHome();debug.ApplyPreset(1490);Req(session.Restoration.CurrentEnergy==1490&&session.Restoration.Stage==5,"final preset");flow.Play();session.DebugPrepareNextRow();Req(session.TryPlacePiece(session.Slots[0],3,3)&&session.Restoration.CurrentEnergy==1500,"final award saved immediately");wait=EditorApplication.timeSinceStartup;stage=3;return;}if(stage==3){if(EditorApplication.timeSinceStartup-wait<5.0)return;Req(session.State==GameState.Playing&&view.ShownStage==5&&view.PresentedEnergy==1500,"restored presentation");int c=view.CompletionPlayCount;session.DebugPrepareNextRow();Req(session.TryPlacePiece(session.Slots[0],3,3)&&session.Restoration.CurrentEnergy==1500,"restored no overflow");Req(view.CompletionPlayCount==c&&!view.FeedbackActive,"no repeat at restored");var stageText=view.transform.Find("Stage").GetComponent<UnityEngine.UI.Text>().text;var energyText=view.transform.Find("Energy").GetComponent<UnityEngine.UI.Text>().text;Req(stageText=="5단계 · 완성 ✓"&&energyText=="별빛 300 / 300","restored HUD Korean completion");session.DebugForceGameOver();session.Retry();session.DebugForceGameOver();flow.ShowHome();Req(flow.Screen==FlowScreen.Home&&!flow.HasSavedRun,"debug flow gameover retry home");Req(errors.Length==0,"runtime errors "+errors);results.Add("PASS exact fill, cell-origin pooled flight, input lock, stage cinematic, cleanup, restored once.");Finish(true,"");}}catch(Exception ex){Finish(false,ex.ToString());}}
 static void Req(bool v,string m){if(!v)throw new Exception("Sprint 6.5 failed: "+m);}static void Finish(bool pass,string fail){EditorApplication.update-=Check;Application.logMessageReceived-=Log;PlayerPrefs.SetInt(PlanetRestoration.DefaultKey,oldEnergy);PlayerPrefs.SetInt(PlanetRestoration.VersionKey,oldVersion);if(hadUnlock)PlayerPrefs.SetInt(PlanetRestoration.Planet02UnlockKey,oldUnlock);else PlayerPrefs.DeleteKey(PlanetRestoration.Planet02UnlockKey);PlayerPrefs.Save();Directory.CreateDirectory("Validation");File.WriteAllText("Validation/sprint65.txt",string.Join("\n",results)+"\n"+(pass?"SPRINT65_PLAY_PASS":fail));if(pass)Debug.Log("SPRINT65_PLAY_PASS");else Debug.LogError(fail);EditorApplication.Exit(pass?0:1);}
